    "name": "fib.exe.asm",
    "contents": "; FIB.EXE [n] â ãã£ããããæ°ã 0 çªãã n çªã¾ã§ï¼n ã¯ 0ã47ããªããã° 20ï¼\nSYS_PUTC    = 1\nSYS_PUTS    = 2\nSYS_PUTDEC  = 6\n\n        .org 0x26000\nstart:\n        ADDI32 sp, sp, -24\n        STORE32_32 lr, sp, 0\n        STORE32_32 r24, sp, 4\n        STORE32_32 r25, sp, 8\n        STORE32_32 r26, sp, 12\n        STORE32_32 r27, sp, 16\n        ; å¼æ°ã 10 é²ã§èª­ã\n        ADDI32 r24, r0, 0               ; n\n        ADDI32 r25, r0, 0               ; èª­ãã æ¡æ°\n.digit: LOAD8U_32 r17, r16, 0\n        ADDI32 r17, r17, -'0'\n        CMPGEUI32 p1, r17, 10\n        BR32 p1, .parsed\n        MULI32 r24, r24, 10\n        ADDR32 r24, r24, r17\n        ADDI32 r16, r16, 1\n        ADDI32 r25, r25, 1\n        JMP32 .digit\n.parsed:\n        ADDI32 r17, r0, 20\n        CMPEQI32 p1, r25, 0\n        SEL32 r24, r17, r24, p1\n        ADDI32 r17, r0, 47              ; fib(47) ã¾ã§ã 32bit ã«å¥ã\n        CMPLTUI32 p1, r24, 48\n        SEL32 r24, r24, r17, p1\n        ADDI32 r25, r0, 0               ; a\n        ADDI32 r26, r0, 1               ; b\n        ADDI32 r27, r0, 0               ; i\n.loop:  ADDI32 r16, r0, s1\n        ADDI32 r23, r0, SYS_PUTS\n        SYSCALL\n        ADDR32 r16, r27, r0\n        ADDI32 r23, r0, SYS_PUTDEC\n        SYSCALL\n        ADDI32 r16, r0, s2\n        ADDI32 r23, r0, SYS_PUTS\n        SYSCALL\n        ADDR32 r16, r25, r0\n        ADDI32 r23, r0, SYS_PUTDEC\n        SYSCALL\n        ADDI32 r16, r0, 10\n        ADDI32 r23, r0, SYS_PUTC\n        SYSCALL\n        ADDR32 r17, r25, r26\n        ADDR32 r25, r26, r0\n        ADDR32 r26, r17, r0\n        ADDI32 r27, r27, 1\n        CMPGEUR32 p1, r24, r27\n        BR32 p1, .loop\n        LOAD32_32 lr, sp, 0\n        LOAD32_32 r24, sp, 4\n        LOAD32_32 r25, sp, 8\n        LOAD32_32 r26, sp, 12\n        LOAD32_32 r27, sp, 16\n        ADDI32 sp, sp, 24\n        RET32\n\ns1:     .asciz \"fib(\"\ns2:     .asciz \") = \"\n"
