    "name": "gdemo.c",
    "contents": "// ã°ã©ãã£ãã¯ç»é¢ã®è¦æ¬ï¼ãã³ãã«ãã­éåã 320 Ã 200ã»256 è²ã§æãï¼æ´æ°ã®åºå®å°æ°ç¹ãæµ®åå°æ°ç¹ã¯ä½¿ããªãï¼ã\n// ã­ã¼ãæ¼ãã¨çµããï¼MyDOS ããã­ã¹ãã®ç»é¢ã«æ»ãï¼\n#include <conio.h>\n#include <gfx.h>\n#include <stdio.h>\n\nint main(void) {\n  gfx_mode(1);\n  for (int i = 1; i < 64; i++) {                // 1ã63ï¼é â æ°´è² â é» â èµ¤ã®ãªããããªè²\n    int t = i * 4, g = 255 - (t * 2 > 255 ? t * 2 - 255 : 255 - t * 2);\n    gfx_palette(i, t, g, 255 - t);\n  }\n  for (int py = 0; py < GFX_H; py++) {\n    int ci = (py - GFX_H / 2) * (3 << 12) / GFX_H;           // èé¨ï¼12bit ã®åºå®å°æ°ç¹ï¼\n    for (int px = 0; px < GFX_W; px++) {\n      int cr = (px - GFX_W * 2 / 3) * (3 << 12) / GFX_H;     // å®é¨\n      int zr = 0, zi = 0, n = 0;\n      while (n < 64) {\n        int rr = zr * zr >> 12, ii = zi * zi >> 12;\n        if (rr + ii > (4 << 12))\n          break;\n        zi = (zr * zi >> 11) + ci;\n        zr = rr - ii + cr;\n        n++;\n      }\n      gfx_pset(px, py, n == 64 ? 0 : n);\n    }\n  }\n  gfx_line(0, 0, GFX_W - 1, 0, 15);\n  gfx_line(0, GFX_H - 1, GFX_W - 1, GFX_H - 1, 15);\n  getch();\n  return 0;\n}\n"
